package be.winnetrie.mod.simpleserverutilities.mine;

import be.winnetrie.mod.simpleserverutilities.Config;import java.util.Set;import be.winnetrie.mod.simpleserverutilities.core.module.SsuModule;import be.winnetrie.mod.simpleserverutilities.core.service.SsuServiceRegistry;import net.minecraft.server.MinecraftServer;
public final class MineModule implements SsuModule{private final MineManager manager;private final MineSetupToolManager tools;public MineModule(MineManager manager,MineSetupToolManager tools){this.manager=manager;this.tools=tools;}@Override public String id(){return "mines";}@Override public Set<String> requiredDependencies() { return Set.of("storage", "regions", "jobs"); }
    @Override public boolean isEnabled() { return Config.ENABLE_MINES.get(); }
    @Override public Set<String> optionalDependencies() { return Set.of("permissions", "holograms", "server_operations", "moderation"); }@Override public void initialize(SsuServiceRegistry services){services.register(MineManager.class,manager);services.register(MineSetupToolManager.class,tools);}@Override public void onServerStarting(MinecraftServer server){manager.load(server);}@Override public void onDependencyStateChanged(MinecraftServer server){manager.refreshOptionalIntegrations();}@Override public void onServerStopping(MinecraftServer server){manager.hideStatusHolograms();manager.save();manager.clearRuntime();tools.clear();}}
